excels.excel:

EXPORT WITH SHEET="月度销量矩阵", HEADER=true,
    MAPPING={"a":"产品","b":"1月","c":"2月","d":"3月"},
    FORMAT={"b":"#,##0","c":"#,##0","d":"#,##0"},
    FORMULAS={
        B5:'SUM(B2:B4)',C5:'SUM(C2:C4)',D5:'SUM(D2:D4)'
    },
    STYLE={ROW 5:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center}},
    GRAPH={TYPE=SURFACE, TITLE="月度销量曲面图", CATEGORY_AXIS=产品, VALUE_AXIS=销量,
           CATEGORIES=["产品A","产品B","产品C"],
           SERIES=[
               {NAME=一月, DATA=[120,150,180]},
               {NAME=二月, DATA=[140,160,200]},
               {NAME=三月, DATA=[160,180,220]}
           ]}
